import json, os, sys, tomllib
env = os.getcwd()
chip = "hibiki"
repo = os.path.join(env, "DangoSys", "buckyball")
chip_dir = os.path.join(repo, "examples", "chips", chip)
docs = os.path.join(env, "log", "hibiki-docs")
chip_docs = os.path.join(chip_dir, "docs")
fails = []
def load(p):
    with open(p, encoding="utf-8") as fh:
        return json.load(fh)
cfg_path = os.path.join(chip_dir, "configs", "generated", "config", "config.json")
if not os.path.isfile(cfg_path):
    print("FAIL: missing", cfg_path, "(run bbdev config --install first)")
    sys.exit(1)
cfg = load(cfg_path)
cores, balldomain = [], {}
for tile in cfg["designs"]["tiles"]:
    for core in tile["cores"]:
        name = core["name"]
        if name not in cores:
            cores.append(name)
        balldomain[name] = core["balldomain"]["_file"]
briefs_path = os.path.join(docs, "core-briefs.json")
icc_path = os.path.join(docs, "inter-core-contract.json")
for p in (briefs_path, icc_path):
    if not os.path.isfile(p):
        print("FAIL: missing", p)
        sys.exit(1)
briefs = load(briefs_path).get("cores") or {}
for c in cores:
    b = briefs.get(c)
    if not isinstance(b, dict):
        fails.append("core-briefs.json: no brief for core " + c)
        continue
    for key in ("mission", "contract", "acceptance", "non_goals"):
        v = b.get(key)
        if not v or (isinstance(v, list) and not any(str(x).strip() for x in v)):
            fails.append("core-briefs.json[" + c + "]." + key + " empty")
    md = os.path.join(chip_docs, "cores", c + ".md")
    if not (os.path.isfile(md) and os.path.getsize(md) > 0):
        fails.append("missing prose brief " + md)
    else:
        text = open(md, encoding="utf-8").read()
        for h in ("Mission", "Contract", "Acceptance", "Non-goals"):
            if h not in text:
                fails.append(md + ": missing section " + h)
icc = load(icc_path)
regions = icc.get("shared_regions") or []
placements = icc.get("ball_placements") or []
if not regions:
    fails.append("inter-core-contract.json: no shared_regions")
for r in regions:
    for k in ("name", "core", "shape", "dtype", "layout", "owner", "readers", "writers", "illegal_input"):
        if not r.get(k):
            fails.append("region " + str(r.get("name")) + " missing " + k)
    if r.get("core") not in cores:
        fails.append("region " + str(r.get("name")) + " names unknown core " + str(r.get("core")))
if not placements:
    fails.append("inter-core-contract.json: no ball_placements")
for p in placements:
    if p.get("core") not in cores:
        fails.append("placement " + str(p.get("op")) + " names unknown core " + str(p.get("core")))
        continue
    bd_file = balldomain[p["core"]]
    bd_path = bd_file if os.path.isabs(bd_file) else os.path.join(repo, bd_file)
    try:
        data = tomllib.load(open(bd_path, "rb"))
    except Exception as exc:
        fails.append("cannot read balldomain " + bd_path + ": " + repr(exc))
        continue
    isa = {int(i["bid"]): i for i in (data.get("ballISA") or []) if "bid" in i and "funct7" in i}
    mapping = {int(m["ballId"]): m for m in (data.get("ballIdMappings") or [])}
    try:
        bid = int(p["bid"])
        f7 = int(p["funct7"])
    except Exception:
        fails.append("placement " + str(p.get("op")) + ": bid/funct7 not integers")
        continue
    e = isa.get(bid)
    if e is None or int(e["funct7"]) != f7:
        fails.append("placement " + str(p.get("op")) + ": bid/funct7 not registered in " + bd_path)
    elif mapping.get(bid, {}).get("ballClass") != p.get("ball_class"):
        fails.append("placement " + str(p.get("op")) + ": ballClass mismatch vs " + bd_path)
if placements:
    f7s = set()
    for p in placements:
        try:
            f7s.add(int(p["funct7"]))
        except Exception:
            pass
    if len(f7s) < 2:
        fails.append("fewer than 2 distinct funct7 across ball_placements: " + str(sorted(f7s)))
boundary = icc.get("boundary") or {}
if boundary.get("name") != "prelookahead_out":
    fails.append("boundary.name must be prelookahead_out")
tensors = boundary.get("tensors") or []
got = {}
for t in tensors:
    got[t.get("name")] = t.get("shape")
    if t.get("dtype") != "float32":
        fails.append("boundary tensor " + str(t.get("name")) + " dtype " + str(t.get("dtype")) + " != float32")
for name, shape in (("x", [1, 25, 512]), ("prelookahead_out", [1, 25, 512])):
    if got.get(name) != shape:
        fails.append("boundary tensor " + name + " shape " + str(got.get(name)) + " != " + str(shape))
for p in (os.path.join(docs, "inter-core-contract.md"), os.path.join(docs, "README.md")):
    if not (os.path.isfile(p) and os.path.getsize(p) > 0):
        fails.append("missing prose doc " + p)
print("cores:", cores)
print("regions:", len(regions), "placements:", len(placements))
for f in fails:
    print("FAIL:", f)
print("RESULT:", "PASS" if not fails else "FAIL")
sys.exit(1 if fails else 0)
