base = {}
if not isinstance(paths, list) or not paths:
    fails.append("paths is not a non-empty list")
    paths = []
for p in paths:
    if not isinstance(p, str) or os.path.isabs(p):
        fails.append("bad path entry " + repr(p))
        continue
    rp = os.path.realpath(os.path.join(env, p))
    if not (rp == env or rp.startswith(env + os.sep)):
        fails.append("path escapes env root: " + p)
        continue
    ok = (os.path.isfile(rp) and os.path.getsize(rp) > 0) or (os.path.isdir(rp) and any(os.scandir(rp)))
    if not ok:
        fails.append("missing or empty: " + p)
    base.setdefault(os.path.basename(p), p)
need = ["config.json", "chip.pb", "cmake.defs", "Cargo.toml", "workloads-elf.bemu.toml", "workloads-elf.verilator.toml", "inter-core-contract.json", "chip.toml"]
missing = [n for n in need if n not in base]
if missing:
    fails.append("paths missing required entries: " + str(missing))
if not any("docs" in p or "cores" in p for p in paths):
    fails.append("no docs path in paths")
result = m.get("result") or {}
if result.get("marker") != "PASSED":
    fails.append("result.marker != PASSED")
vals = result.get("values") or {}
for k in ("chip", "model", "config_dir"):
    if k not in vals:
        fails.append("result.values missing " + k)
if vals.get("chip") != "hibiki":
    fails.append("values.chip != hibiki")
if "CosyVoice2" not in str(vals.get("model")):
    fails.append("values.model does not name CosyVoice2")
cd = vals.get("config_dir")
if not isinstance(cd, str) or cd not in paths:
    fails.append("values.config_dir must be one of paths")
elif not os.path.isdir(os.path.join(env, cd)):
    fails.append("values.config_dir is not a directory: " + cd)
print("manifest paths:", len(paths), "values:", vals)
for f in fails:
    print("FAIL:", f)
print("RESULT:", "PASS" if not fails else "FAIL")
sys.exit(1 if fails else 0)
